import{_ as n,o as i,c as r,a3 as t}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"ATLAS Terminal","description":"ATLAS-Browser-Terminal mit ANSI-Farben, optionalem SSH, Oh-My-Posh-Themes und serverseitiger Nerd-Font.","frontmatter":{"title":"ATLAS Terminal","description":"ATLAS-Browser-Terminal mit ANSI-Farben, optionalem SSH, Oh-My-Posh-Themes und serverseitiger Nerd-Font."},"headers":[],"relativePath":"projects/atlas-plugins/terminal.md","filePath":"projects/atlas-plugins/terminal.md","lastUpdated":1793123358000}'),a={name:"projects/atlas-plugins/terminal.md"};function s(o,e,l,d,u,h){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="atlas-terminal" tabindex="-1">ATLAS Terminal <a class="header-anchor" href="#atlas-terminal" aria-label="Permalink to &quot;ATLAS Terminal&quot;">​</a></h1><p>ATLAS Terminal ist ein eigenständiges Plugin-Repository für ein authentifiziertes Browser-Terminal. Es bietet ANSI-Farben, eine einstellbare Schriftgröße, auswählbare Oh-My-Posh-Themes und optional eine SSH-Verbindung zu einem serverseitig festgelegten Ziel.</p><p>Die Oberfläche ist auf Deutsch, Englisch und Französisch verfügbar. Die Sprachauswahl wird im Browser gespeichert und kann zusätzlich über den URL-Parameter <code>language</code> vorgegeben werden.</p><h2 id="repository-und-installation" tabindex="-1">Repository und Installation <a class="header-anchor" href="#repository-und-installation" aria-label="Permalink to &quot;Repository und Installation&quot;">​</a></h2><ul><li>GitHub: <a href="https://github.com/rockbaer2007/atlas-terminal-plugin" target="_blank" rel="noreferrer">rockbaer2007/atlas-terminal-plugin</a></li><li>Installationsseite: <a href="https://rockbaer2007.github.io/atlas-terminal-plugin/install.html" target="_blank" rel="noreferrer">ATLAS Terminal hinzufügen</a></li><li>Repository-Manifest: <a href="https://raw.githubusercontent.com/rockbaer2007/atlas-terminal-plugin/main/repository.json" target="_blank" rel="noreferrer">repository.json</a></li><li>Plugin-Version: <code>0.1.10</code></li></ul><p>Füge in ATLAS Administration unter <strong>Plugins → Repository hinzufügen</strong> den Typ <strong>Plugin</strong> hinzu und verwende die Manifest-URL. Prüfe das Repository und installiere anschließend das Plugin-Paket. Der ATLAS-Host muss ein kompatibles Terminal-Backend enthalten.</p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><ul><li>Browser-Terminal mit ANSI-Farben</li><li>lokal einstellbare Schriftgröße</li><li>Oh-My-Posh-Themes für lokale Bash-Sitzungen</li><li>Meslo LGM Nerd Font wird vom Home-Assistant-Server geladen; Clients benötigen keine lokale Font-Installation</li><li>optionales SSH-Ziel mit serverseitig konfiguriertem Host, Benutzer, Schlüssel und <code>known_hosts</code></li><li>Hostschlüsselprüfung bleibt aktiv; das Browserfenster kann kein beliebiges SSH-Ziel angeben</li><li>eigenständige Versionierung des Frontends im Plugin-Repository</li><li>einklappbare Token-Einstellungen: beim Verbinden geschlossen, nach dem Trennen oder Sitzungsende wieder geöffnet</li><li>lokale Shell-Sitzungen starten im Dateisystem-Root <code>/</code> des ATLAS-Containers statt in <code>/app</code>; SSH behält das Standardverzeichnis des Zielservers</li></ul><h2 id="nerd-font-einrichten" tabindex="-1">Nerd Font einrichten <a class="header-anchor" href="#nerd-font-einrichten" aria-label="Permalink to &quot;Nerd Font einrichten&quot;">​</a></h2><p>Lege <code>MesloLGMNerdFontMono-Regular.ttf</code> und <code>MesloLGMNerdFontMono-Bold.ttf</code> in <code>/config/www/fonts/</code> oder direkt in <code>/config/www/</code> ab. Home Assistant stellt sie unter <code>/local/fonts/</code> beziehungsweise <code>/local/</code> bereit. Das Terminal lädt die Schriftdateien von dort.</p><h2 id="voraussetzungen-und-sicherheit" tabindex="-1">Voraussetzungen und Sicherheit <a class="header-anchor" href="#voraussetzungen-und-sicherheit" aria-label="Permalink to &quot;Voraussetzungen und Sicherheit&quot;">​</a></h2><p>Das Repository enthält das Plugin-Frontend, ist aber <strong>kein eigenständiger SSH-Server und kein Home-Assistant-Add-on</strong>. Shell-, Supervisor- und WebSocket-Funktionen stellt der ATLAS-Host bereit. Ab Plugin <code>0.1.10</code> nennen Katalog, Paket und Manifest die App/Runtime <code>&gt;=0.1.215 &lt;0.2.0</code>, Host <code>administration-local</code> und Home Assistant <code>&gt;=2026.8</code>. Die frühere Angabe <code>&gt;=0.2.0-alpha.79</code> bezeichnete eine Framework-Version und war im Feld <code>compatibility.atlas</code> falsch. App- und Framework-Versionen sind getrennte Versionsreihen.</p><p>Bestehende gemeinsame Terminal-Einträge können die alte Angabe weiterhin enthalten. Sichere zuerst HA und den gemeinsamen Plugin-Stand; korrigiere nur den nachgewiesenen Versionsfehler mit Prüfung der aktuellen Revision. Aktivierungen, andere Anforderungen und übrige Einträge bleiben erhalten. Ein Repository-Refresh allein ändert den gespeicherten Stand nicht. Vorhandene Rücksicherungen behalten ihre Anforderungen; sie dürfen nicht ungeprüft umgeschrieben oder durch Umgehen der Kompatibilitätsprüfung eingespielt werden. Die korrigierten Angaben migrieren weder Tokens noch Plugin-Daten. Das Laden der Meslo-Schrift benötigt App/Add-on <code>0.1.214</code>; Root-Startverzeichnis und einklappbare Token-Einstellungen benötigen <code>0.1.215</code> oder neuer.</p><p>Das Terminal ist standardmäßig deaktiviert. Aktiviere es erst, nachdem auf dem ATLAS-Host ein starkes, zufälliges Zugriffstoken mit mindestens 32 URL-sicheren Zeichen eingerichtet wurde. Die lokale Shell läuft mit den Berechtigungen des ATLAS-Prozesses. Im Home-Assistant-App/Add-on-Betrieb können Supervisor-Berechtigungen auch administrative <code>ha</code>-Befehle ermöglichen. Behandle den Terminalzugriff daher wie administrativen Zugriff.</p><p>Das Zugriffstoken bleibt im lokalen Browserspeicher und wird beim Verbindungsaufbau über das WebSocket-Subprotokoll, nicht über eine URL, übertragen. Die Token-Einstellungen klappen beim Verbinden ein und nach dem Trennen oder Sitzungsende wieder aus. Ohne gespeichertes Token sind die Einstellungen beim ersten Aufruf geöffnet. Skripte derselben Website können auf diesen Speicher zugreifen. Verwende das Terminal nur in einem vertrauenswürdigen Browserprofil.</p><h2 id="status-und-lizenz" tabindex="-1">Status und Lizenz <a class="header-anchor" href="#status-und-lizenz" aria-label="Permalink to &quot;Status und Lizenz&quot;">​</a></h2><p>Das Plugin wird als <strong>experimentell</strong> geführt, da es ein passendes ATLAS-Backend voraussetzt. Die Lizenz ist <a href="https://github.com/rockbaer2007/atlas-terminal-plugin/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT</a>.</p>',17)])])}const m=n(a,[["render",s]]);export{g as __pageData,m as default};
